T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Wszyscy członkowie z rangą, poziomem i wersją Oasis. Prawy przycisk na wierszu: zmień rangę."
T["Alle Oasis-Nutzer bekommen eine Warnung, wenn ein Gebannter in ihrer Gruppe ist, sie einlaedt oder handeln will - und sehen es im Tooltip."] = "Wszyscy użytkownicy Oasis dostają ostrzeżenie, gdy zbanowany gracz jest w ich grupie, zaprasza ich lub chce handlować - i widzą to w podpowiedzi."
