T["Alle Zusagen auf die Gruppen verteilen und sofort einladen und sortieren."] = "Rozdziel wszystkie zapisy na grupy, od razu zaproś i posortuj."
T["Alle ab dem gewaehlten Rang (Rang 1 = Gildenmeister) sehen diese Zentrale und duerfen Module und Durchsagen fuer die Gilde aendern. Die Grenze legt nur der Gildenmeister fest."] = "Wszyscy od wybranej rangi w górę (ranga 1 = mistrz gildii) widzą to centrum i mogą zmieniać moduły i ogłoszenia gildii. Granicę ustala tylko mistrz gildii."
T["Alle ab dem gewaehlten Rang (Rang 1 = Gildenmeister) sehen diese Zentrale und duerfen Module, Erscheinungsbild und Durchsagen fuer die Gilde aendern. Die Grenze legt nur der Gildenmeister fest."] = "Wszyscy od wybranej rangi w górę (ranga 1 = mistrz gildii) widzą to centrum i mogą zmieniać moduły, wygląd i ogłoszenia gildii. Granicę ustala tylko mistrz gildii."
T["Alle ab dem gewaehlten Rang sehen diese Zentrale und duerfen Module, Durchsagen und Events fuer die Gilde aendern."] = "Wszyscy od wybranej rangi w górę widzą to centrum i mogą zmieniać moduły, ogłoszenia i wydarzenia gildii."
