T["Alle, die es koennen"] = "Każdy, kto potrafi"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Burning Adrenaline: NATYCHMIAST wybiegnij z rajdu (zaraz zginiesz).\nAll: Pełne zasoby na starcie - użyj wszystkiego.\nTank: Ustalcie kolejność tanków (Adrenaline na tanku).\nDD: Nie stój przed smokiem ani za nim."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Nie pozwólcie, by 8 Firesworn zginęło blisko rajdu (eksplozja).\nTank: Każdy tank addów odciąga swojego Firesworn, warlocki banishują.\nHealer: Dispel, pilnuj tanków addów.\nDD: Najpierw Garr, addy tylko na komendę."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Dwa Core Ragery tankować z dala od bossa, nie zabijać.\nTank: Zmiana tanka Golemagga, gdy Magma Splash ma za dużo stacków.\nDD: Tylko Golemagg."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Najpierw 4 priestów, leczą się nawzajem.\nTank: Trzymaj Sulfurona i priestów osobno.\nDD: Przerywać! Zatrzymać Dark Mending priestów."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Ochrona przed ogniem! Wrath of Ragnaros odrzuca melee - potem wracaj.\nAll: Faza synów (po 3 min lub gdy się zanurzy): zabić wszystkich Sons of Flame.\nTank: Drugi tank gotowy, gdy pierwszy zostanie odrzucony.\nHealer: Rozstawieni, ranged nie za blisko (Lava Burst).\nDD: Melee: pilnuj many, ranged trzymaj dystans."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet się stackuje - ranged za filary, żeby zszedł.\nTank: Dwóch tanków za filarami, Wing Buffet odrzuca.\nDD: Onyxia Scale Cloak obowiązkowy."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Natychmiast zdejmij Gehennas' Curse (słabsze leczenie).\nAll: Wyjdź z Rain of Fire.\nTank: Dwa Flamewakery tankować osobno.\nDD: Najpierw Flamewakery, potem Gehennas."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Natychmiast zdejmij Lucifron's Curse i Impending Doom (magowie/druidzi, priesti/paladyni).\nTank: Dwóch strażników tankować osobno - mind control!\nHealer: Stójcie rozstawieni, dispel na graczach pod mind control.\nDD: Najpierw strażnicy, potem Lucifron."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Living Bomb: NATYCHMIAST wybiegnij z rajdu!\nAll: Inferno - z dala od bossa, dispel Ignite Mana.\nTank: Trzymaj środek, przy Inferno wyjdź na chwilę.\nDD: Melee odsuwa się przy Inferno."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Uważaj na odbicie magii/tarczę obrażeń strażników - wtedy przerwij obrażenia.\nTank: Jeden strażnik na tanka, magowie owcują elitarnych strażników.\nDD: Najpierw strażnicy-healerzy (Flamewaker Healer)."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Nigdy nie stój przed Onyxią ani za nią (oddech i uderzenie ogonem).\nAll: Faza 2 (65%): unikaj kul ognia, nie wchodź do wejść jaskiń.\nAll: Faza 3 (40%): fear - Fear Ward/Tremor Totem w gotowości, omijaj szczeliny lawy.\nTank: Onyxia bokiem przy ścianie, głowa z dala od rajdu.\nTank: Faza 2: zbierz whelpy. Faza 3: natychmiast odzyskaj aggro.\nHealer: Tank ma priorytet, w fazie 2 stójcie rozstawieni.\nDD: Poczekaj na 3 ataki tanka. Faza 2: najpierw whelpy."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "All: Nigdy nie stój przed Onyxią ani za nią (oddech/ogon).\nPhase 2 from 65%: unikaj kul ognia, whelpy zabijać od razu.\nPhase 3 from 40%: fear - Grounding Totem i Fear Ward w gotowości.\nTank: Onyxia tyłem do ściany, głowa z dala od rajdu.\nTank: w fazie 3 natychmiast odzyskaj aggro.\nHealer: najpierw tank, w fazie 2 stójcie rozstawieni.\nDPS: pełne obrażenia dopiero po 3 Sunderach tanka.\nDPS: faza 2: whelpy przed Onyxią."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Panic - Fear Ward/Tremor Totem, hunterzy: Tranquilizing Shot na Frenzy.\nAll: Wyjdź z ognia lawy na ziemi.\nTank: Magmadar tyłem do rajdu.\nDD: Ranged rozstawieni z tyłu."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Faza 1: dragonkiny z obu stron, uważaj na class calle.\nAll: Faza 3 (20%): szkielety wstają ponownie - zabić jeszcze raz.\nTank: Nefarian przy ścianie, fear - Fear Ward.\nHealer: Class call na priestów: leczenie rani - uważaj.\nDD: Hunterzy/warriorzy: uważaj na class calle (brak broni, postawa)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Faza 1: niszczyć jaja (mind control przez kulę), przejmować addy.\nAll: Po wszystkich jajach: boss w sali - Fire Nova.\nTank: Zbierz addy przy schodach.\nDD: Najpierw magowie i dragonkiny."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frenzy - hunterzy: Tranquilizing Shot.\nTank: Dwóch tanków, uwaga na Wing Buffet.\nDD: Onyxia Scale Cloak obowiązkowy."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Shadow of Ebonroc leczy bossa - tank z debuffem się zmienia.\nTank: Dwóch tanków zmienia się przy Shadow.\nDD: Onyxia Scale Cloak obowiązkowy."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "All: cel roju: wybiegnij.\nTank: tank infernali na uboczu.\nHealer: zdejmuj sen, gdzie się da.\nDPS: ignoruj infernale, wszystko w bossa."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Knockback - stań przy ścianie.\nTank: Dwóch tanków, Knock Away dzieli aggro.\nDD: Mortal Strike na tanku: healerzy w gotowości."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Teleportuje się - kto ma aggro, niech nie ucieka.\nAll: Zdejmij Shazzrah's Curse, Arcane Explosion: melee trzyma dystans.\nTank: Po każdym blinku od razu wracaj do niego.\nHealer: Dispel (Deaden Magic)."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "All: natychmiast wyjdź z Death and Decay.\nTank: trzymaj środek, nie ruszaj się podczas Frost Nova.\nHealer: szybko wylecz cel Ice Blocka.\nDPS: ranged szeroko rozstawieni (łańcuch Iceboltów)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Dwa z pięciu rodzajów oddechu na tydzień - oddechu unikasz za rogiem.\nAll: Hourglass Sand na Bronze affliction.\nTank: Tankuj przy bramie, rajd za rogiem.\nDD: Tranquilizing Shot na Frenzy."
