T["Aus: Die Gilde sieht nur deine Charaktere, die in der Gilde sind. Bank- und Chill-Twinks bleiben privat. An: Alle deine Charaktere werden als Twinks angezeigt."] = "Wył.: gildia widzi tylko twoje postacie będące w gildii. Alty bankowe i chillowe zostają prywatne. Wł.: wszystkie twoje postacie są pokazywane jako alty."
T["Aus: Wer in der Warteschlange einen Gegner sucht, erscheint nur noch auf der Deathroll-Seite"] = "Wył.: gracze szukający przeciwnika pojawiają się tylko na stronie Deathroll"
T["Aus: alle animierten Gilden-Emojis sind fuer jeden sofort benutzbar"] = "Wył.: wszystkie animowane emoji gildii są od razu dostępne dla każdego"
T["Aus: das Fenster verschwindet. Zurueck mit /oa builds."] = "Wył.: okno znika. Przywróć je przez /oa builds."
T["Aus: der Hinweis nennt nur Name und Ort"] = "Wył.: powiadomienie pokazuje tylko nazwę i miejsce"
T["Aus: keine Hinweise mehr, wenn jemand ein Level erreicht - Bosse und Legacy bleiben"] = "Wył.: koniec powiadomień o zdobytych poziomach - bossy i legacy zostają"
T["Aus: neue Abzeichen und Gilden-Titel werden nicht mehr in die Gildenchronik eingetragen"] = "Wył.: nowe odznaki i tytuły gildii nie trafiają już do kroniki gildii"
T["Aus: niemand schreibt bei Gold-Abzeichen und Gilden-Titeln eine Zeile in den Gildenchat, auch wenn es persoenlich eingeschaltet ist"] = "Wył.: nikt nie pisze na czacie gildii o złotych odznakach i tytułach gildii, nawet jeśli ma to włączone u siebie"
T["Aus: niemand sendet seine Position an die Gilde (Gildenkarte und Minimap-Punkte bleiben leer)"] = "Wył.: nikt nie wysyła swojej pozycji do gildii (mapa gildii i punkty na minimapie zostają puste)"
T["Aus: nur Klassen-Buffs (Ausdauer, Intelligenz, Segen ...)"] = "Wył.: tylko buffy klasowe (Stamina, Intellect, Blessings ...)"
T["Aus: nur Totenkopf und Kreuz (Kill-Reihenfolge)"] = "Wył.: tylko czaszka i krzyżyk (kolejność zabijania)"
T["Aus: nur bei Spielern, die DU als schlecht markiert hast"] = "Wył.: tylko u graczy oznaczonych przez CIEBIE jako źli"
