T["Automatisch: Oasis legt alle 10 Minuten und beim Ausloggen einen Schnappschuss in den Gespeicherten Variablen ab (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Das Programm Tools/oasis_export.py liest die Datei, macht JSON daraus und kann es an eure Weboberflaeche schicken. Addons haben keinen Internetzugriff - das ist der sichere Weg."] = "Automatycznie: co 10 minut i przy wylogowaniu Oasis zapisuje migawkę w zapisanych zmiennych (WTF/Account/<konto>/SavedVariables/Oasis.lua). Program Tools/oasis_export.py czyta plik, zamienia go na JSON i może wysłać na waszą stronę. Addony nie mają dostępu do internetu - to bezpieczna droga."
