T["Den Knopf kannst du auch direkt an der Minimap mit der Maus verschieben."] = "Przycisk możesz też przeciągać myszą wokół minimapy."
T["Den Raid-Simulator gibt es nur in der Entwicklerversion."] = "Symulator rajdu jest dostępny tylko w wersji deweloperskiej."
T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "Plan rajdu mogą edytować tylko władze gildii, liderzy rajdu i asystenci rajdu."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "WoW nie może tu pokazać drzewka talentów tej klasy. Tekst eksportu skopiujesz poniżej."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "Usunąć całą historię z %s? Zapisane wiadomości też znikną."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "Zamówienie trafia do wszystkich rzemieślników z tą recepturą - kto ma czas, ten je bierze."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "Zamówienie zostaje wycofane dla wszystkich."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "Zamawiający dostanie informację, że gotowe."
T["Der Auftraggeber bekommt Bescheid."] = "Zamawiający zostanie powiadomiony."
T["Der Basar ist leer"] = "Bazar jest pusty"
T["Der Brachland-Chat mit seinen Spruechen"] = "Czat Barrens i jego teksty"
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "Klient nie pozwala Oasis włączyć logu walki - wpisz /combatlog samodzielnie."
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "Klient nie zwraca teraz umiejętności - poczekaj chwilę po zalogowaniu."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "Kompas lochów: który loch pasuje i co tam dla Ciebie wypada."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "Wróg nie stał przed Tobą. Stał za Tobą. Przez cały czas."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "Lider grupy może zrobić Cię asystentem."
T["Der Handwerker bekommt sofort einen Hinweis und meldet sich."] = "Rzemieślnik od razu dostaje powiadomienie i się odezwie."
T["Der Hintergrund der Legenden"] = "Tło legend"
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "Zawartość wybranej sekcji. Przegląd pokazuje, kto jest online, co się zbliża i co nowego."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "Walka była najpierw zablokowana i została zapisana później."
T["Der Katalog ist noch leer."] = "Katalog jest jeszcze pusty."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "Przycisku nie da się już przeciągać myszą"
T["Der Link gilt fuer alle Leitungen."] = "Link obowiązuje dla wszystkich oficerów."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "Rynek korzysta z cen z addonu AH Midas. Gdy Ty lub ktoś z gildii zeskanuje AH z Midas, ta strona się odblokuje."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "Przycisk przy minimapie lub /oa otwiera Oasis. Kreska w prawym górnym rogu zmienia okno w wąski pasek."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "Rejestrowanie czasu gry jest wył. Włącz je, a Oasis będzie uczyć się z każdym wieczorem."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "Ranga Oasis to gildyjna ranga w Oasis - rośnie dzięki wspólnej grze, pomaganiu, rzemiosłu, wydarzeniom i odznakom."
T["Der Offizierschat wird nie geteilt."] = "Czat oficerów nigdy nie jest udostępniany."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "Kanał oficerów (/o) z historią - tylko dla rang z uprawnieniem do czatu oficerów."
T["Der Online-Sound dieser Person ist bei dir aus."] = "Dźwięk online tej osoby jest u Ciebie wyciszony."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "Krawędź okna Oasis świeci w Twoim kolorze"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "Pierścień pokazuje, kto nie ma otwartych punktów."
T["Der Steinfresser"] = "Pożeracz kamieni"
T["Der Termin liegt in der Vergangenheit."] = "Ten termin jest w przeszłości."
T["Der ganze Verlauf mit Emojis - verpasste Nachrichten holt Oasis beim Einloggen nach"] = "Cała historia z emoji - pominięte wiadomości Oasis pobiera przy logowaniu"
T["Der gelbe Strich links in der Liste zeigt das an."] = "Wskazuje na to żółta kreska po lewej stronie listy."
