T["Diamantrahmen"] = "Diamentowa ramka"
T["Die Bank aktualisiert sich, wenn jemand mit Oasis den Gildentresor oeffnet."] = "Bank aktualizuje się, gdy ktoś z Oasis otworzy skarbiec gildii."
T["Die Bank besucht. Mal kurz nachzaehlen."] = "Wizyta w banku. Tylko szybko przeliczę."
T["Die Bannliste ist leer."] = "Lista banów jest pusta."
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "Statystyki postaci są niedostępne w tym kliencie."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "Pole czatu zostało użyte przez Oasis (np. przycisk 'Szepnij'), potem wpisano /target."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "Pole czatu zostało użyte przez Oasis (np. przycisk 'Szepnij'), potem wpisano tam komendę /cast."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "Pole czatu zostało użyte przez Oasis, potem wpisano /focus."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "Pole czatu zostało użyte przez Oasis, potem wpisano komendę zaklęcia."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "Mapy lochów nie mają współrzędnych. Kliknij tutaj, a potem w miejsce na mapie, w którym stoisz. Po zrobieniu tego w dwóch odległych miejscach Oasis pokaże Ciebie i Twoją grupę na mapie - dla całej gildii."
T["Die Einladung ist nicht mehr da."] = "Tego zaproszenia już nie ma."
T["Die Farbe der Legenden"] = "Kolor legend"
T["Die Gilde abstimmen lassen - jeder Spieler hat eine Stimme, das Ergebnis ist live"] = "Daj gildii zagłosować – jeden głos na gracza, wyniki na żywo"
T["Die Gilde begruesst (moin, hallo, servus ...)"] = "Powitano gildię (cześć, hej, siema ...)"
T["Die Gilde bekommt Bescheid"] = "Gildia zostanie powiadomiona"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "Gildia widzi, komu odpowiadasz. Domyślnie: wył."
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "Gildia widzi Twoje ognisko na mapie przez %d minut."
T["Die Gilde sieht dein Feuer 15 Minuten auf der Karte."] = "Gildia widzi Twoje ognisko na mapie przez 15 minut."
T["Die Gilde sieht deine Einladung. Sobald jemand mitspielt, geht es los."] = "Gildia widzi Twoje zaproszenie. Gdy ktoś dołączy, gra się zaczyna."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "Gildia widzi w kronice Twoje osiągnięcia"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "Gildia nie szuka teraz niczego z tego lochu."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "Twoja gildia nie przyznaje jeszcze punktów łupu - Twoje wartości pojawią się, gdy liderzy rajdu rozpoczną rajd."
T["Die Gildenbank wurde noch nicht gelesen"] = "Bank gildii nie został jeszcze odczytany"
T["Die Gildenbank wurde noch nie gelesen. Sobald jemand mit Oasis den Gildentresor oeffnet, steht hier alles - fuer die ganze Gilde."] = "Bank gildii nie został jeszcze odczytany. Gdy ktoś z Oasis otworzy skarbiec gildii, wszystko pojawi się tutaj – dla całej gildii."
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "Władze gildii wyznaczają liderów rajdu i asystentów w Korona > Moduły > Rajdy & łup (po nazwie lub od rangi gildii). W trwającym rajdzie liczą się też lider rajdu i asystenci."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "Władze gildii wyznaczają liderów rajdu w Korona > Moduły > Rajdy & łup. W trwającym rajdzie liczą się też lider rajdu i asystenci."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "Władze gildii wyznaczają liderów rajdu w Korona > Moduły > Rajdy & łup. W trwającym rajdzie liczy się też lider rajdu."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "Władze gildii pozwalają szukać grupy dopiero od wyższej rangi."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "Władze gildii pozwalają na ankiety dopiero od wyższej rangi."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "Władze gildii zablokowały Ci efekty dźwiękowe."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "Władze gildii wyłączyły szukanie towarzyszy."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "Władze gildii wyłączyły otwarte zaproszenia - wyzwij kogoś bezpośrednio."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "Władze gildii ustalają w Korona > Moduły, które rangi to mogą."
T["Die Gildenleitung sehen nur Raenge bis %d (%s). Dein Rang: %d."] = "Władze gildii widzą tylko rangi do %d (%s). Twoja ranga: %d."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "Wyszukiwarka gildii WoW pomaga w szukaniu - neutralnie, bez reklam."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "Limit ustala tylko mistrz gildii. Ranga 1 = mistrz gildii."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "Przyciski wpisują komendę w linię czatu - wykona się dopiero po Enter."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Skróty są też w ustawieniach klawiszy WoW w AddOns > Oasis. Esc zamyka okno Oasis (nie w walce - tam Esc należy do gry)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Skróty są też w ustawieniach klawiszy WoW w AddOns > Oasis. Esc zamyka okno Oasis, jeśli ostatnie kliknięcie było w nim."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "Pasek jest od zalogowania i zostaje - X na oknie zamyka tylko okno."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "Pasek chowa się w górę; najedź myszą na górną krawędź, a zjedzie (tylko gdy jest zadokowany u góry)"
T["Die Leute im Brachland reden ab und zu ueber dich"] = "Ludzie w Barrens czasem o Tobie gadają"
T["Die Oasis gratuliert."] = "Oasis życzy wszystkiego najlepszego."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "Procent porównuje ocenę przedmiotu dla Twojej roli, a nie całe Twoje obrażenia. Efekty to szacunki."
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "Wiersz rezerwacji pojawia się tylko, gdy jesteś w grupie lub rajdzie"
T["Die Schnellen und die Toten"] = "Szybcy i martwi"
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "Statystyka nie zwraca teraz czytelnej wartości."
T["Die Waechter der Sande"] = "The Scale of the Sands"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "Otwarto mapę świata. Gdzie to była północ?"
T["Die Wuerfe sind echte /roll-Ergebnisse vom Server. Seid ihr zu weit auseinander, gleicht Oasis sie per Addon-Nachricht ab."] = "Rzuty to prawdziwe wyniki /roll z serwera. Jeśli jesteście za daleko od siebie, Oasis synchronizuje je wiadomością addonu."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "Centrum Twojej gildii. W 30 sekund się połapiesz - oto najważniejsze."
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "Prawdziwy pasek u góry od razu pokazuje każdą zmianę"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "Pierwsze 20 pkt wytrzymałości daje po 1 zdrowia, każdy kolejny 10."
T["Die ersten animierten Gilden-Emojis"] = "Pierwsze animowane emoji gildii"
T["Die ganze Weltkarte mit einem Charakter erkunden"] = "Odkryj całą mapę świata jedną postacią"
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "Chroniona funkcja została zablokowana. Dokładna przyczyna jest jeszcze nieznana."
T["Die meiste Beute der Gilde in den letzten 30 Tagen. Glaenzt es? Meins!"] = "Najwięcej łupu w gildii w ostatnich 30 dniach. Błyszczy? Moje!"
T["Die meiste Zeit mit Gildenmitgliedern in Gruppen"] = "Najwięcej czasu w grupach z członkami gildii"
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "Najwięcej biegów ducha w gildii. Na cmentarzu stoi ławka z Twoim imieniem."
T["Die meisten Nachrichten im Gildenchat"] = "Najwięcej wiadomości na czacie gildii"
T["Die meisten Naechte online"] = "Najwięcej nocy online"
T["Die meisten Screenshots der Gilde"] = "Najwięcej zrzutów ekranu w gildii"
T["Die meisten Spruenge der Gilde"] = "Najwięcej skoków w gildii"
T["Die meisten Tode der Gilde in den letzten 30 Tagen"] = "Najwięcej śmierci w gildii w ostatnich 30 dniach"
T["Die meisten Tode der letzten 7 Tage"] = "Najwięcej śmierci w ostatnich 7 dniach"
T["Die meisten Todeswuerfeln-Siege der Gilde"] = "Najwięcej wygranych w Deathroll w gildii"
T["Die meisten Todeswuerfeln-Siege im letzten Monat (Saison)"] = "Najwięcej wygranych w Deathroll w zeszłym miesiącu (sezon)"
T["Die meisten Umarmungen und Jubel fuer andere"] = "Najwięcej uścisków i wiwatów dla innych"
T["Die meisten Wiederbelebungen"] = "Najwięcej wskrzeszeń"
T["Die meisten besuchten Gebiete"] = "Najwięcej odwiedzonych stref"
T["Die meisten epischen Gegenstaende der Gilde"] = "Najwięcej epickich przedmiotów w gildii"
T["Die meisten erledigten Auftraege der Gilde"] = "Najwięcej zrealizowanych zamówień w gildii"
T["Die meisten gefangenen Fische"] = "Najwięcej złowionych ryb"
T["Die meisten vollen Taschen der Gilde"] = "Najwięcej pełnych toreb w gildii"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "Najnowsze ogłoszenie jest przez 3 dni na górze przeglądu."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "Nie znaleziono jeszcze pasującej statystyki postaci."
T["Die seltensten Gilden-Emojis"] = "Najrzadsze emoji gildii"
T["Die vergessenen Teiche"] = "The Forgotten Pools"
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "Pełne teksty licencji są w folderze Oasis: CREDITS.txt, LICENSE i LICENSE-MIT.txt."
T["Dienstag"] = "Wtorek"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "Te odznaki Twoja karta profilu pokazuje jako pierwsze - u Ciebie i w gildii."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "Te rangi gildii (0 = mistrz gildii) mogą głosować w radzie łupów."
T["Diese Hinweise ausschalten"] = "Wyłącz te powiadomienia"
T["Diese Quest hat %s, nicht du."] = "To zadanie ma %s, nie Ty."
T["Diese Quest ist nicht in deinem Questlog."] = "Tego zadania nie ma w Twoim dzienniku zadań."
T["Diese Regel gibt es schon."] = "Ta reguła już istnieje."
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "Te strony są małymi przyciskami na zwiniętym pasku Oasis - jedno kliknięcie je otwiera."
T["Diese Sitzung: %d EP in %s"] = "Ta sesja: %d XP w %s"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "Ten język zacznie działać po następnym /reload - kliknij tutaj, by przeładować."
T["Diese Taktik ist noch leer."] = "Ta taktyka jest jeszcze pusta."
T["Diese Woche"] = "Ten tydzień"
T["Diese Woche hat noch niemand eingezahlt."] = "W tym tygodniu nikt jeszcze nic nie wpłacił."
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "W tym tygodniu wszystko jeszcze otwarte - kto zaczyna?"
T["Diese Woche noch ruhig."] = "W tym tygodniu na razie spokój."
T["Diese Woche:"] = "Ten tydzień:"
T["Diesen Monat noch keine Spiele."] = "W tym miesiącu jeszcze brak gier."
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "Ta postać jest na innym koncie WoW i wskazała Cię jako maina. Liczy się w gildii jako Twój alt tylko po Twoim potwierdzeniu."
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "Ten klient nie ma API kolekcji. /oa probe sammlung pokaże szczegóły."
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "Ten klient nie zwraca pomiarów addonów (brak C_AddOnProfiler)."
T["Dieser Client liefert keine Rufdaten - du siehst nur die Staende der anderen."] = "Ten klient nie zwraca danych reputacji - widzisz tylko stany innych."
T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "Ten klient nie zgłasza rzadkich wrogów (brak API). /oa probe rares pokaże szczegóły."
T["Dieser Termin steht im WoW-Kalender. Anmelden kannst du dich dort."] = "To wydarzenie jest w kalendarzu WoW. Tam możesz się zapisać."
T["Diplomat"] = "Dyplomata"
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "Nie brakuje Ci niczego, co ma gildia - nieźle!"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "Szept do samego siebie. Kto inny tak dobrze Cię słucha?"
