T["Doppelte Oasis-XP fuer %d Stunden - viel Spass!"] = "Podwójne XP Oasis przez %d godz. - miłej zabawy!"
T["Doppelte Oasis-XP fuer alle in der Gilde, 48 Stunden lang. Alle bekommen eine Durchsage."] = "Podwójne XP Oasis dla wszystkich w gildii przez 48 godzin. Wszyscy dostaną ogłoszenie."
T["Doppelte Oasis-XP fuer alle in der Gilde. Alle mit Oasis bekommen eine Durchsage."] = "Podwójne XP Oasis dla całej gildii - start w dowolnej chwili. Wszyscy z Oasis dostaną ogłoszenie."
T["Doppelter Rechtsklick wirft aus, Fang-Statistik in der Uebersicht"] = "Podwójny prawy przycisk zarzuca wędkę, statystyki połowów w przeglądzie"
