T["Du bist in keiner Gruppe. Sobald du in einer Gruppe oder einem Raid bist, steht hier alles fuer den Pull."] = "Nie jesteś w grupie. Gdy będziesz w grupie lub rajdzie, znajdziesz tu wszystko do pulla."
