T["Gerade braucht niemand etwas, das du hast.\nUebrige Questitems in deinen Taschen werden automatisch angeboten."] = "Nikt teraz nie potrzebuje niczego, co masz.\nZbędne przedmioty zadań z toreb są oferowane automatycznie."
T["Gerade gibt es nichts gemeinsam zu tun."] = "Teraz nie ma nic do zrobienia razem."
T["Gerade hat niemand aus der Gilde dieselben Quests.\nSobald Mitglieder mit Oasis gleiche Quests annehmen, stehen sie hier."] = "Nikt z gildii nie ma teraz tych samych zadań.\nGdy członkowie z Oasis przyjmą te same zadania, pojawią się tutaj."
T["Gerade hilft keines deiner Teile"] = "Żaden z twoich przedmiotów teraz nie pomaga"
T["Gerade ist keiner deiner Quest-Partner online."] = "Żaden z twoich partnerów do zadań nie jest teraz online."
T["Gerade ist niemand aus der Gilde im Stufenbereich online."] = "Nikt z gildii w tym zakresie poziomów nie jest teraz online."
T["Gerade ist niemand aus der Gilde in deiner Gegend oder deinem Level online."] = "Nikt z gildii w twojej okolicy ani na twoim poziomie nie jest teraz online."
T["Gerade ist niemand faellig."] = "Nikt teraz nie jest w kolejce."
T["Gerade ist niemand im Sprachkanal."] = "Na kanale głosowym nikogo teraz nie ma."
T["Gerade ist niemand in deinem Levelbereich online.\nStarte rechts trotzdem eine Gruppe - wer online kommt und passt, bekommt Bescheid."] = "Nikt w twoim zakresie poziomów nie jest teraz online.\nMimo to załóż grupę po prawej - kto wejdzie i pasuje, dostanie powiadomienie."
T["Gerade ist niemand online - schau spaeter nochmal rein."] = "Nikt nie jest teraz online - zajrzyj później."
T["Gerade ist sonst niemand online."] = "Nikt inny nie jest teraz online."
T["Gerade kannst du keinen Wunsch erfuellen.\nOasis meldet sich, sobald du etwas Gesuchtes lootest."] = "Teraz nie możesz spełnić żadnego życzenia.\nOasis da znać, gdy zdobędziesz coś poszukiwanego."
T["Gerade kein Lagerfeuer gemeldet."] = "Brak zgłoszonych ognisk."
T["Gerade kein Lagerfeuer gemeldet.\nZuende selbst eins an - die Gilde bekommt Bescheid."] = "Brak zgłoszonych ognisk.\nRozpal własne - gildia dostanie powiadomienie."
T["Gerade kein Upgrade dabei"] = "Teraz brak ulepszeń"
T["Gerade kein XP-Wochenende."] = "Teraz nie ma Double XP."
T["Gerade liegt nichts unter dem fairen Preis."] = "Teraz nic nie jest poniżej uczciwej ceny."
T["Gerade nichts Besonderes - einfach losziehen!"] = "Teraz nic szczególnego - po prostu ruszaj!"
T["Gerade nichts dabei. Sobald jemand mit Oasis ein passendes handelbares Teil hat, erscheint es hier."] = "Teraz nic. Gdy ktoś z Oasis będzie miał pasujący wymienialny przedmiot, pojawi się tutaj."
T["Gerade nichts geplant."] = "Teraz nic nie zaplanowano."
T["Gerade nichts unter dem fairen Preis. Nach dem naechsten Scan wird neu geprueft."] = "Teraz nic poniżej uczciwej ceny. Ponowne sprawdzenie po następnym skanie."
