T["Gerade sucht niemand Mitstreiter. Starte selbst eine Suche!"] = "Nikt teraz nie szuka towarzyszy. Zacznij szukać samodzielnie!"
T["Gerade sucht niemand Mitstreiter.\nWaehle eine Challenge und klick 'Mitstreiter suchen'."] = "Nikt nie szuka towarzyszy.\nWybierz wyzwanie i kliknij \"Szukaj towarzyszy\"."
T["Gerade sucht niemand.\nStarte links eine Suche - passende Rollen bekommen sofort einen Hinweis."] = "Nikt teraz nie szuka.\nZacznij szukać po lewej - pasujące role od razu dostaną powiadomienie."
T["Gerade sucht niemand.\nStarte rechts eine Gruppe - wer die passende Rolle spielt, bekommt sofort Bescheid."] = "Nikt teraz nie szuka.\nZałóż grupę po prawej - gracze z pasującą rolą od razu dostaną powiadomienie."
T["Gerade teilt niemand handelbare Teile. Geteilt wird nur, was nicht seelengebunden im Inventar oder in der Bank liegt."] = "Nikt teraz nie udostępnia wymienialnych przedmiotów. Udostępniane są tylko przedmioty niezwiązane z duszą z toreb lub banku."
T["Gerade teilt niemand seine Position."] = "Nikt teraz nie udostępnia swojej pozycji."
T["Gerade teilt niemand seine Position.\nWer Oasis hat und 'Meine Position teilen' anlaesst, erscheint hier."] = "Nikt nie udostępnia swojej pozycji.\nKto ma Oasis i włączone 'Udostępniaj moją pozycję', pojawi się tutaj."
T["Gerade wartet niemand.\nKlick 'Ich will spielen' - die Gilde bekommt Bescheid."] = "Nikt nie czeka.\nKliknij 'Chcę zagrać' - gildia dostanie powiadomienie."
T["Gerade will niemand etwas von dir."] = "Nikt teraz niczego od ciebie nie potrzebuje."
