T["Niemand steht kurz vor Respektvoll oder Ehrfuerchtig (ab 75 %)."] = "Nikt nie jest blisko Revered ani Exalted (od 75 %)."
T["Niemand. Stummschalten geht per Rechtsklick auf einen Namen im Gildenchat."] = "Nikt. Wyciszysz kogoś prawym przyciskiem na nazwie w czacie gildii."
T["Nimm Quests an - Oasis zeigt dir, wer aus der Gilde dieselben hat."] = "Bierz zadania – Oasis pokaże, kto z gildii ma te same."
T["Ninja-Markierung entfernen"] = "Usuń oznaczenie ninja"
T["Noch Standard-Einstellungen."] = "Wciąż ustawienia domyślne."
T["Noch aus"] = "Jeszcze wył."
T["Noch eine Runde - ich will meine Ehre zurueck!"] = "Jeszcze jedna runda - chcę odzyskać honor!"
T["Noch gesperrt"] = "Jeszcze zablokowane"
T["Noch hat niemand Material beigetragen."] = "Nikt jeszcze nie dołożył materiałów."
T["Noch kein Crit erfasst. Kritische Treffer zaehlen automatisch, sobald du allein in der offenen Welt kaempfst."] = "Brak zapisanych critów. Trafienia krytyczne liczą się automatycznie, gdy walczysz solo w otwartym świecie."
T["Noch kein Highlight - die Woche ist jung."] = "Brak wyróżnienia – tydzień dopiero się zaczął."
T["Noch kein Kampf ausgewertet"] = "Brak zapisanej walki"
T["Noch kein Muster - dafuer braucht es mehrere Versuche."] = "Brak wzorca – potrzeba kilku prób."
T["Noch kein Protokoll."] = "Brak logu."
T["Noch kein Protokoll. Es wird gelesen, wenn jemand mit Oasis die Bank oeffnet."] = "Brak logu. Jest odczytywany, gdy ktoś z Oasis otworzy bank."
T["Noch kein Ready-Check"] = "Brak ready checka"
T["Noch kein Ready-Check gelaufen."] = "Nie było jeszcze ready checka."
T["Noch kein Scan"] = "Brak skanu"
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "Brak skanu - gdy ktoś zeskanuje z Midas, pojawią się tu okazje."
T["Noch kein Scan in der Gilde."] = "Brak skanu w gildii."
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "Brak terminu - zgłoś zainteresowanie, a lider rajdu będzie wiedział, kiedy pasuje."
T["Noch kein Termin geplant. Oben links: Was, Tag, Uhrzeit - dann 'Event anlegen'."] = "Brak zaplanowanych wydarzeń. U góry po lewej: co, dzień, godzina - potem 'Utwórz wydarzenie'."
T["Noch kein Tod - weiter so!"] = "Jeszcze bez śmierci - tak trzymaj!"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "Nie zapisano jeszcze zabicia rzadkiego wroga."
T["Noch kein lesbarer eigener Crit erfasst. Neue kritische Treffer werden automatisch aufgezeichnet."] = "Nie zapisano jeszcze Twojego czytelnego crita. Nowe trafienia krytyczne zapisują się automatycznie."
T["Noch kein positiver Einzelrekord gemeldet."] = "Nie zgłoszono jeszcze dodatniego rekordu pojedynczego trafienia."
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Nikt nie udostępnił jeszcze cooldownów - kto ma Transmute, Mooncloth lub Salt Shaker, pojawi się tutaj."
T["Noch keine Abzeichen"] = "Brak odznak"
T["Noch keine Abzeichen."] = "Brak odznak."
T["Noch keine Antworten."] = "Brak odpowiedzi."
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Brak danych o ekwipunku - weź na cel i obejrzyj gracza w pobliżu (Oasis sam ogląda członków grupy)."
T["Noch keine Berufe gelernt."] = "Brak wyuczonych profesji."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "Brak łupu z tego lochu w logu gildii."
T["Noch keine Beute erfasst"] = "Brak zapisanego łupu"
T["Noch keine Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Brak zapisanego łupu (od jakości Rare, do zmiany)."
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Brak kandydatów. Wpisz nazwę wyżej - kliknięcie statusu przełącza go dalej."
T["Noch keine Bio."] = "Brak bio."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Brak danych - ekwipunek dotrze przy następnej synchronizacji Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Brak danych - członkowie wysyłają pomiar co 15 min (od tej wersji)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Brak danych - otwórz raz okno kolekcji albo noś wierzchowce i pety w torbach. Członkowie gildii z Oasis pojawią się tu, gdy będą online."
T["Noch keine Daten aus der Gilde."] = "Brak danych z gildii."
T["Noch keine Daten von der Gilde."] = "Brak danych od gildii."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Brak danych. Gdy członkowie gildii zalogują się z Oasis, pojawią się tu ich ID rajdów."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Brak zapisanych przejść lochów."
T["Noch keine Dungeons geplant."] = "Brak zaplanowanych lochów."
T["Noch keine Durchsagen."] = "Brak ogłoszeń."
T["Noch keine Durchsagen. Schreib links die erste - Ueberschrift, Nachricht, senden."] = "Brak ogłoszeń. Napisz pierwsze po lewej - nagłówek, wiadomość, wyślij."
T["Noch keine Eintraege."] = "Brak wpisów."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Nie użyto jeszcze emoji - ulubione z wyboru emoji pojawią się tutaj."
T["Noch keine Favoriten - Diamant anklicken."] = "Brak ulubionych - kliknij diament."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Brak ulubionych - kliknij gwiazdkę lub prawy przycisk na dźwięku."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Brak ulubionych.\nPrawy przycisk na emoji zapisze je tutaj."
T["Noch keine Fluesternachrichten."] = "Brak szeptów."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Brak szeptów. Napisz do kogoś z gildii!"
T["Noch keine Fraktionen entdeckt."] = "Nie odkryto jeszcze frakcji."
T["Noch keine Gilden-News."] = "Brak nowości gildii."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Brak celów gildii. Utwórz pierwszy - np. legendarną broń lub materiały na rajd."
T["Noch keine Items verlinkt."] = "Brak podlinkowanych przedmiotów."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Brak raportów z walk. Po pierwszej walce z bossem znajdziesz tu każdą próbę – z osią czasu śmierci i powtarzającymi się wzorcami."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Brak raportów z walk. Po pierwszej walce z bossem znajdziesz tu każdą próbę."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Brak kandydatów. Graj z ludźmi spoza gildii - dobrze oceniani gracze bez gildii trafią tutaj."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Brak kombinacji.\nShift+klik na kilku emoji, potem Zapisz."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Brak kontaktów. Dołącz do grupy z innymi użytkownikami Oasis - Oasis zapamięta ich tutaj, nawet bez gildii."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Brak kamieni milowych. Zdobywaj poziomy, ucz się profesji - tu powstaje Twoja historia."
T["Noch keine Meldungen aus der Gilde."] = "Brak zgłoszeń z gildii."
T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "Brak graczy spoza gildii.\nKażdy, z kim byłeś w grupie, trafi tu automatycznie."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Brak momentów - po prostu graj, Oasis wszystko zapisze."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "Brak wiadomości na czacie oficerów. Wszystko, co od teraz pojawi się na /o, trafi tutaj."
T["Noch keine Nachrichten. Alles, was ab jetzt im Gildenchat geschrieben wird, landet hier."] = "Brak wiadomości. Wszystko, co od teraz pojawi się na czacie gildii, trafi tutaj."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Brak pozycji - mapa zapełni się, gdy członkowie z Oasis ruszą w świat."
T["Noch keine Positionen."] = "Brak pozycji."
T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "Brak postów. Kliknij 'Nowa migawka' albo aparat na pasku Oasis!"
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Brak cen. Gdy ktoś zeskanuje AH z Midas, pojawią się tutaj."
T["Noch keine Profile gespeichert."] = "Brak zapisanych profili."
T["Noch keine Punkte"] = "Brak punktów"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "Brak punktów.\nGdy oficer rozpocznie rajd, wszyscy obecni dostaną punkty za udział."
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Brak zapisanych dni rajdowych. Lider rajdu (z Oasis) zapisuje je automatycznie przy każdym zabiciu bossa."
T["Noch keine Regeln"] = "Brak reguł"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Brak reguł. Wybierz szybki szablon albo dodaj własną wyżej."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "Brak znanych receptur.\nOtwórz raz okna profesji – Oasis udostępni je wtedy gildii."
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "Nikt nie udostępnił jeszcze receptur.\n\nGdy ktoś z Oasis otworzy okno profesji, receptury pojawią się tutaj. Kto ma jaką profesję, widzisz już teraz:"
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Brak danych o reputacji. Pojawią się automatycznie, gdy członkowie z Oasis będą online."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Nikt nie udostępnił jeszcze kolekcji. Pojawią się tu, gdy członkowie gildii z Oasis będą online."
T["Noch keine Sets."] = "Brak zestawów."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Brak obserwacji. Gdy ktoś z Oasis zobaczy rzadkiego wroga, pojawi się tutaj."
T["Noch keine Spiele."] = "Brak gier."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Brak znanych godzin gry. Oasis uczy się z każdym wieczorem, gdy jesteś online - i przejmuje profile innych."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Brak wyszukiwania. Wpisz poziomy i kliknij „Szukaj” - gracze z gildią są ukrywani."
T["Noch keine Taktiken."] = "Brak taktyk."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Brak taktyk. Liderzy rajdu mogą dodać krótką taktykę dla każdego bossa - wszyscy widzą ją tutaj i po wzięciu bossa na cel."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Brak znanych talentów. Członkowie z Oasis udostępniają je automatycznie; inni gracze: weź na cel i obejrzyj (prawy przycisk > Inspect) albo otwórz to ponownie z celem."
T["Noch keine Umfragen."] = "Brak ankiet."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Brak przydziałów - pojawią się tu, gdy liderzy rajdu rozdadzą łup."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Brak wartości - po następnej walce zobaczysz, kto prowadzi."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Brak preferowanych dni - zaznacz, kiedy możesz."
T["Noch keine Wunschtage gemeldet."] = "Nie zgłoszono jeszcze preferowanych dni."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Brak celów. Dodaj jeden wyżej - Oasis odhaczy go automatycznie."
T["Noch keine Zusagen - sei der Erste!"] = "Brak zapisów - bądź pierwszy!"
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "Brak znanych – gdy ktoś z Oasis będzie miał zadanie do tego lochu, pojawi się tutaj."
T["Noch keine eigene Beute"] = "Brak własnego łupu"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Brak Twojego zapisanego łupu (od jakości Rare, do zmiany)."
T["Noch keiner bestaetigt - der Twink traegt dich mit /oa twink als Main ein."] = "Nikt jeszcze nie potwierdził - alt ustawia Cię jako maina przez /oa twink."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "Na razie pusto. Usiądź przy ognisku i dodaj\nbuffa w przeglądzie przez „+”."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "Na razie pusto. Usiądź przy ognisku i dodaj\nbuffa po prawej przez „+”."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Brak zapisu - wybierz rolę poniżej"
T["Noch nicht bereit"] = "Jeszcze nie gotowy"
T["Noch nicht fuer die Gilde uebernommen:"] = "Jeszcze nie przyjęte dla gildii:"
T["Noch nicht kalibriert - Kalibrieren?"] = "Brak kalibracji - skalibrować?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "Lista życzeń jest pusta.\nWpisz wyżej, czego potrzebujesz - każdy z Oasis zobaczy to w tooltipach i przy łupie."
T["Noch nichts aufgezeichnet."] = "Nic jeszcze nie zapisano."
T["Noch nichts benutzt."] = "Nic jeszcze nie użyto."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Nic nie zablokowano. Gdy WoW zablokuje Oasis, zobaczysz tu, którą funkcję i co Oasis robił tuż przedtem."
T["Noch nichts eingelesen"] = "Nic nie zaimportowano"
T["Noch nichts erledigt."] = "Nic jeszcze nie ukończono."
T["Noch nichts geangelt."] = "Nic jeszcze nie złowiono."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Nic nie zapisano - prawy przycisk na wiadomości: Zapisz wiadomość."
T["Noch nichts im Feed. Folge Leuten aus der Gilde - ihre Posts landen dann hier."] = "Twój feed jest pusty. Obserwuj ludzi z gildii - ich posty trafią tutaj."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Nic się jeszcze nie wydarzyło - ruszajcie tworzyć historię!"
T["Noch nichts passiert."] = "Na razie nic."
T["Noch nichts passiert. Geht spielen!"] = "Nic się jeszcze nie wydarzyło. Idźcie grać!"
T["Noch nichts reserviert"] = "Nic nie zarezerwowano"
T["Noch nichts reserviert - ein Item pro Termin."] = "Nic nie zarezerwowano - jeden przedmiot na termin."
T["Noch nichts reserviert."] = "Nic nie zarezerwowano."
T["Noch nichts verkauft."] = "Nic jeszcze nie sprzedano."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Nic jeszcze nie rozdano. Gdy zadziała reguła, pojawi się to tutaj."
T["Noch nie direkt mit dir abgeglichen"] = "Nigdy nie zsynchronizowano bezpośrednio z Tobą"
T["Noch niemand - die Gilde ist informiert."] = "Jeszcze nikt – gildia została powiadomiona."
T["Noch niemand angefluestert."] = "Nie szepnąłeś jeszcze do nikogo."
T["Noch niemand aus der Gilde hat es uebrig."] = "Nikt z gildii nie ma tego jeszcze na zbyciu."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Nikt z gildii z Twoją specjalizacją nie udostępnia jeszcze talentów (użytkownicy Oasis robią to automatycznie)."
T["Noch niemand bekannt. Wer das Rezept hat, teilt es automatisch beim Oeffnen des Berufsfensters."] = "Nikt jeszcze nieznany. Kto ma recepturę, udostępnia ją automatycznie po otwarciu okna profesji."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Nikt nie odszedł, odkąd Oasis prowadzi zapis."
T["Noch niemand gemeldet - sei der Erste!"] = "Nikt się jeszcze nie zgłosił - bądź pierwszy!"
T["Noch niemand gestorben. Respekt!"] = "Nikt jeszcze nie zginął. Szacun!"
T["Noch niemand hat dich erwaehnt."] = "Nikt Cię jeszcze nie wspomniał."
T["Noch niemand sonst kennt das Rezept."] = "Nikt inny nie zna jeszcze tej receptury."
T["Noch niemand teilt seine Handelsbilanz."] = "Nikt nie udostępnia jeszcze bilansu handlu."
T["Noch niemand teilt seine Handelsbilanz. Links 'Meine Handelsbilanz teilen' einschalten - dann geht's los."] = "Nikt nie udostępnia jeszcze bilansu handlu. Włącz po lewej 'Udostępniaj mój bilans handlu' - i zaczynamy."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Nikt nie udostępnia jeszcze bilansu handlu. Włącz poniżej 'Udostępniaj bilans' - i zaczynamy."
T["Noch offen"] = "Wciąż otwarte"
T["Noch offen: "] = "Wciąż otwarte: "
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Nikt nie udostępnia jeszcze przez Oasis przedmiotów na handel. Im więcej członków używa Oasis, tym pełniej tu będzie."
T["Noch zu uebergeben"] = "Do przekazania"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Za mało danych na godzinę szczytu"
T["Nochmal klicken zum Loeschen"] = "Kliknij ponownie, aby usunąć"
T["Nochmal klicken: alle"] = "Kliknij ponownie: wszystkie"
T["Norden oben  -  Punkte am Rand sind ausserhalb der Reichweite"] = "Północ u góry  ·  punkty na krawędzi są poza zasięgiem"
T["Normal"] = "Normalny"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "Zwykle Oasis powiadamia tylko o szukaniach, które sam masz jeszcze otwarte"
T["Notiz"] = "Notatka"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "Notatka (klasa, kontakt, wrażenie ...)"
T["Notiz (z.B. zahle 5s/Stueck) ..."] = "Notatka (np. płacę 5s/szt.) …"
T["Notiz ..."] = "Notatka ..."
T["Notiz an den Plundermeister (optional)"] = "Notatka dla mistrza łupów (opcjonalnie)"
T["Notiz bearbeiten"] = "Edytuj notatkę"
T["Notiz der Gildenleitung"] = "Notatka władz gildii"
T["Notiz von %s: %s"] = "Notatka od %s: %s"
T["Notiz zu %s"] = "Notatka o %s"
T["Notiz zum ausgewaehlten Mitspieler, z.B. 'super Heiler, netter Typ'"] = "Notatka o wybranym graczu, np. „świetny healer, miły gość”"
T["Notiz zur Person"] = "Notatka o osobie"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "Notatka do szukania (czas, miejsce spotkania) ..."
T["Notiz zur Suche ..."] = "Notatka do szukania …"
T["Notiz, z.B. 'Kochen + Schmieden, kommt vorbei' ..."] = "Notatka, np. „Cooking + Blacksmithing, wpadajcie” …"
T["Notiz, z.B. 'Mats bringe ich mit' ..."] = "Notatka, np. „Maty przyniosę” …"
T["Notiz, z.B. 'ab Level 17, Treffpunkt Mondbruch'"] = "Notatka, np. „od poziomu 17, spotkanie w Moonbrook”"
T["Notiz, z.B. 'bis Freitag'"] = "Notatka, np. 'do piątku'"
T["Notiz: "] = "Notatka: "
T["Notizen sehen und schreiben nur Offiziere."] = "Notatki widzą i piszą tylko oficerowie."
T["November"] = "Listopad"
T["Novize"] = "Nowicjusz"
T["Novizen-Hoehlenforscher"] = "Początkujący grotołaz"
T["Nur %s"] = "Tylko %s"
T["Nur %s zeigen"] = "Pokaż tylko %s"
T["Nur Abende vorschlagen"] = "Proponuj tylko wieczory"
T["Nur Anfuehrer oder Assistenten koennen verteilen."] = "Łup mogą rozdawać tylko lider lub asystenci."
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Tylko baner i trzy kolumny (kto online, co się dzieje, co dalej) - bez kafelków i wiersza wyróżnień"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Tylko lochy, w których łup jest lepszy od Twojego założonego ekwipunku."
T["Nur Eintraege dieser Person"] = "Tylko wpisy tej osoby"
T["Nur Farbverlauf"] = "Tylko gradient"
T["Nur Gegner im Kampf"] = "Tylko wrogowie w walce"
T["Nur Gilde mit Oasis, nie in Instanzen"] = "Tylko gildia z Oasis, nigdy w instancjach"
T["Nur Gildenleitung"] = "Tylko władze gildii"
T["Nur Gruppenquests beruecksichtigen"] = "Tylko zadania grupowe"
T["Nur Helfer online"] = "Tylko pomocnicy online"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "Powiadamiaj tylko o ogniskach w mojej strefie"
T["Nur Mains ab Level"] = "Tylko mainy od poziomu"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Szukanie grupy mogą zacząć tylko członkowie do tej rangi (10 = wszyscy)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Nową ankietę mogą zacząć tylko członkowie do tej rangi (10 = wszyscy)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Tylko członkowie z Oasis. Udostępniane: brakujące przedmioty do zadań, zbędne przedmioty do zadań i zadania do udostępnienia."
T["Nur Oasis-Spieler"] = "Tylko gracze z Oasis"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Tylko gracze z Oasis: każdy widzi to we własnym języku."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Ten kanał (/o) widzą tylko oficerowie i władze gildii."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "Rozdawać mogą tylko mistrz łupów, lider lub asystenci."
T["Nur Rezepte, die du selbst kannst"] = "Tylko receptury, które sam znasz"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "Tylko receptury, które ktoś online może teraz wykonać"
T["Nur Upgrades"] = "Tylko ulepszenia"
T["Nur aktuelles Gebiet"] = "Tylko bieżąca strefa"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Tylko do własnej grupy, dla mapy lochu"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Tylko podgląd - edycja: władze, liderzy rajdu, asystenci rajdu"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "Tylko podgląd – rysuje lider rajdu"
T["Nur auf diesem PC"] = "Tylko na tym PC"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "Tylko ukryte - kliknij tutaj, aby wrócić."
T["Nur ausgeblendet - klick hier, um zurueckzukehren. Aufgeben geht nur ueber 'Aufgeben'."] = "Tylko ukryte – kliknij tutaj, aby wrócić. Poddać się można tylko przez 'Poddaj się'."
T["Nur bei dir"] = "Tylko u Ciebie"
T["Nur bei dir - die Gilde sieht ihre eigene Farbe."] = "Tylko u Ciebie – gildia widzi własny kolor."
T["Nur bei dir gespeichert"] = "Zapisane tylko u Ciebie"
T["Nur bei dir sichtbar - nichts wird gesendet."] = "Widoczne tylko dla Ciebie - nic nie jest wysyłane."
T["Nur bei gleicher Klasse und Spezialisierung."] = "Tylko przy tej samej klasie i specjalizacji."
T["Nur das Noetigste"] = "Tylko niezbędne"
T["Nur der Gildenmeister kann das aendern."] = "Może to zmienić tylko mistrz gildii."
T["Nur der Gildenmeister kann die Grenze aendern."] = "Limit może zmienić tylko mistrz gildii."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "Tylko mistrz gildii, najwyżej 10 rang."
T["Nur der Gruppenleiter kann eine Suche starten."] = "Szukanie może zacząć tylko lider grupy."
T["Nur der Gruppenleiter kann suchen"] = "Szukać może tylko lider grupy"
T["Nur die Gildenleitung kann das aendern."] = "Mogą to zmienić tylko władze gildii."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Ranking Deathroll mogą zresetować tylko władze gildii."
T["Nur die wichtigsten Bereiche sind an."] = "Włączone są tylko najważniejsze sekcje."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "Słyszy go tylko ta osoba (jeśli ma Oasis)."
T["Nur diesen Abschnitt posten"] = "Opublikuj tylko tę część"
T["Nur eigene Posts lassen sich loeschen."] = "Usuwać można tylko własne posty."
T["Nur falls WoW die Rang-Rechte nicht liefert: bis zu welchem Gildenrang andere als Offizier gelten (fuer die Pruefung empfangener Daten)."] = "Tylko gdy WoW nie podaje uprawnień rang: do której rangi gildii inni liczą się jako oficerowie (do sprawdzania odebranych danych)."
T["Nur fehlende"] = "Tylko brakujące"
T["Nur fuer Anfuehrer und Assistenten"] = "Tylko dla lidera i asystentów"
T["Nur fuer Gildenmeister und Offiziere."] = "Tylko dla mistrza gildii i oficerów."
T["Nur fuer Gildenmitglieder mit Oasis, nie in Instanzen"] = "Tylko dla członków gildii z Oasis, nigdy w instancjach"
T["Nur fuer Offiziere"] = "Tylko dla oficerów"
T["Nur fuer Schlachtzugsleiter"] = "Tylko dla liderów rajdu"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "Tylko dla liderów i asystentów rajdu"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "Tylko dla ankiet, które zacząłeś lub w których głosowałeś"
T["Nur fuer den Schlachtzugsleiter"] = "Tylko dla lidera rajdu"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "Widoczne tylko dla Ciebie - w nagłówku rozmowy z %s."
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "Tylko dla Ciebie: po walce jedna linia z czasem trwania i pierwszą śmiercią"
T["Nur fuer die Fehlersuche. Standard: aus"] = "Tylko do debugowania. Domyślnie: wył."
T["Nur fuer die Gildenleitung"] = "Tylko dla władz gildii i oficerów"
