T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "Oasis łączy Twoje postacie w gildii w jednego gracza. Zmienisz to później w Ustawienia > Profil i kopia zapasowa."
T["Oasis funktioniert trotzdem fuer dich: dein Profil, Ziele, Dungeons und Sammlungen sind da."] = "Oasis i tak działa dla Ciebie: Twój profil, cele, lochy i kolekcje są na miejscu."
