T["Oasis ist bereit"] = "Oasis jest gotowy"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis potrafi bardzo dużo. Wybierz, czego chcesz używać - reszta zostaje na razie wyłączona i możesz ją włączyć w każdej chwili w 'Odkrywaj'."
T["Oasis laedt noch - gleich nochmal versuchen."] = "Oasis jeszcze się ładuje – spróbuj za chwilę."
T["Oasis laeuft"] = "Oasis działa"
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Po każdej walce Oasis odczytuje wbudowany miernik obrażeń Blizzarda - także w instancjach."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Po każdej walce Oasis odczytuje wbudowany miernik obrażeń Blizzarda - log walki jest w WoW Forever zablokowany dla addonów. Inni potrzebują Oasis 0.5.577 lub nowszego. Wartości ukrywane przez Blizzarda (np. w instancjach) się nie liczą."
