T["So geht es: /combatlog an, kaempfen, dann ImportCrits.bat im Oasis-Ordner doppelklicken und /reload."] = "Jak: włącz /combatlog, walcz, potem kliknij dwukrotnie ImportCrits.bat w folderze Oasis i wpisz /reload."
