T["So lange bleiben die Totenkoepfe auf der Weltkarte sichtbar."] = "Jak długo czaszki są widoczne na mapie świata."
T["So lange bleibt ein gemeldetes Lagerfeuer fuer die Gilde auf der Karte."] = "Jak długo zgłoszone ognisko zostaje na mapie dla gildii."
T["So lange hat jeder Zeit zu waehlen. Wer nichts waehlt, passt."] = "Tyle czasu każdy ma na wybór. Kto nic nie wybierze, pasuje."
T["So lange steht ein gruenes NEU vor neuen Mitgliedern."] = "Jak długo nowi członkowie mają zielone NOWY."
T["So lange wird derselbe Wunsch nicht erneut gemeldet"] = "Przez ten czas to samo życzenie nie jest zgłaszane ponownie"
T["So lange wird eine angepinnte Nachricht oben im Gildenchat gezeigt"] = "Jak długo przypięta wiadomość jest widoczna u góry czatu gildii"
T["So oft erinnert Oasis Mitglieder mit veralteter Version ans Aktualisieren"] = "Jak często Oasis przypomina członkom ze starą wersją o aktualizacji"
