T["So spielst du es"] = "Jak tym grać"
T["So viel Prozent vom Topf gehen vor dem Aufteilen an die Gildenbank."] = "Taki procent puli trafia do banku gildii przed podziałem."
T["So viele Minuten muss ein Spieler warten, bevor er die naechste Suche sendet (0 = keine Grenze)."] = "Ile minut gracz musi czekać przed wysłaniem kolejnego ogłoszenia (0 = bez limitu)."
T["So viele Stueck eines Auftrags zaehlen hoechstens fuer das Handwerker-Abzeichen"] = "Najwyżej tyle sztuk z zamówienia liczy się do odznaki rzemieślnika"
T["So viele schlechte Bewertungen aus der Gilde braucht es, bevor vor einem Spieler gewarnt wird."] = "Tyle złych ocen z gildii potrzeba, zanim pojawi się ostrzeżenie o graczu."
