T["Sobald du in einer Gruppe bist, siehst du hier, ob alle bereit sind."] = "Gdy będziesz w grupie, zobaczysz tu, czy wszyscy są gotowi."
T["Sobald du in einer Gruppe einen Dungeon betrittst, merkt sich Oasis deine Mitspieler."] = "Gdy wejdziesz z grupą do lochu, Oasis zapamięta Twoich towarzyszy."
T["Sobald ein Offizier einen Punkte-Raid startet, bekommen alle, die dabei sind, Einsatz-Punkte. Rechts siehst du, wie es funktioniert."] = "Gdy oficer rozpocznie rajd punktowany, wszyscy obecni dostają punkty wysiłku. Po prawej zobaczysz, jak to działa."
T["Sobald ein Termin steht, meldest du dich mit deiner Rolle an - die Raidleitung teilt dich dann einer Gruppe zu."] = "Gdy wydarzenie jest ustalone, zapisz się ze swoją rolą - lider rajdu przydzieli Cię do grupy."
T["Sobald jemand mit Oasis ein passendes handelbares Teil hat, erscheint es hier - mit Hinweis."] = "Gdy ktoś z Oasis ma pasujący przedmiot na wymianę, pojawi się on tutaj - z powiadomieniem."
