T["Weltkarte aufdecken findest du unter Bereiche > Karte."] = "Odkrywanie mapy świata znajdziesz w Sekcje > Mapa."
T["Weltkarte aufdecken findest du unter der Weltkarte und unter Bereiche > Karte."] = "Odkrywanie mapy świata znajdziesz pod mapą świata oraz w Sekcje > Mapa."
T["Weltkarte oeffnen"] = "Otwórz mapę świata"
T["Wen moechtest du herausfordern? Namen eingeben oder jemanden anvisieren."] = "Kogo chcesz wyzwać? Wpisz imię lub weź kogoś na cel."
T["Wenn jemand etwas bei dir oder deinem Beruf bestellt (und wenn dein Auftrag fertig ist)"] = "Gdy ktoś zamówi coś u Ciebie lub w Twojej profesji (i gdy Twoje zamówienie jest gotowe)"
T["Wenn jemand online kommt"] = "Gdy ktoś wchodzi online"
T["Wer"] = "Kto"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Kto wysyła dane odrzucane przez innych (brak uprawnień, sfałszowany autor, zmyślone wpisy). Niezmodyfikowane Oasis praktycznie nigdy tego nie robi - to wskazówka, nie dowód."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Kto zgłosi zainteresowanie, pojawi się tu na pasującym miejscu. Gdy jest wydarzenie, zapisujesz się bezpośrednio na karcie."
T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Kto danego wieczoru dostał już przedmiot na need, przy need spada za wszystkich bez przedmiotu (ta sama ranga rzutu)."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "Kto w gildii ma ten przedmiot na liście życzeń"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Kto widzi tę sekcję w nawigacji (władze gildii zawsze widzą wszystko)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Kto opuścił gildię lub został usunięty. Gdy ktoś wróci, Oasis powiadomi władze gildii."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Kto widzi koronę u góry. Bez uprawnień jest szara i otwiera tylko podgląd."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Kto zarezerwował przedmiot na wydarzenie, ma przy need pierwszeństwo przed wszystkimi."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Kto może przypiąć wiadomość na górze czatu gildii"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "Nie wiadomo jeszcze, kto może zapraszać - zaloguj się raz mainem, a Oasis zapamięta władze gildii."
T["Wer geht mit nach %s? Ich suche %s"] = "Kto idzie na %s? Szukam %s"
T["Wer hat ...?"] = "Kto ma ...?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "Kto ma przedmiot do zadania, którego potrzebujesz? I komu możesz pomóc?"
T["Wer hat gerade %s am Lagerfeuer? Ich komme vorbei!"] = "Kto ma teraz %s przy ognisku? Wpadnę!"
T["Wer hat was bekommen"] = "Kto co dostał"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "Kto może księgować punkty (udział/łup) w rajdzie."
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf. Wird sofort gespeichert."] = "Kto może księgować punkty (udział/łup) w rajdzie. Zapisuje się od razu."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "Kto w grupie lub rajdzie ma jakie buffy - i czego brakuje"
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Kto w grupie lub rajdzie ma jakie buffy - i kto może dać brakujące"
T["Wer ist bereit? Ampeln je Spieler"] = "Kto jest gotowy? Światła statusu dla każdego gracza"
T["Wer ist da?"] = "Kto tu jest?"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "Kto ma już w tym tygodniu lockout, kto jest wolny i ma dostęp - mainy i alty"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "Kto jest w gildii, jaka ranga, kto ma stare Oasis."
T["Wer ist online"] = "Kto jest online"
T["Wer ist online, wo, mit welchen Berufen - und wer gewinnt das Level-Rennen"] = "Kto jest online, gdzie, z jakimi profesjami - i kto wygrywa wyścig poziomów"
T["Wer ist online?"] = "Kto jest online?"
T["Wer ist wann online"] = "Kto jest kiedy online"
T["Wer ist wie weit"] = "Kto jest jak daleko"
T["Wer kann was herstellen - Rezepte, Material, Preise und Auftraege der Gilde"] = "Kto co potrafi wytworzyć - receptury, materiały, ceny i zamówienia gildii"
T["Wer kann was herstellen, Markt, Gildenbank"] = "Kto co wytwarza, rynek, bank gildii"
T["Wer kann's?"] = "Kto to zrobi?"
T["Wer koennte mit: %s"] = "Kto mógłby iść: %s"
T["Wer koennte mit?"] = "Kto mógłby iść?"
T["Wer mitkommen will"] = "Kto chce iść"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "Kto często bierze udział, a mało dostał, ma pierwszeństwo przy 'Need'. Co tydzień część punktów przepada."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "Kto zgłosi się z pasującą rolą, od razu dostaje zaproszenie do Twojej grupy."
T["Wer sieht die Gildenleitung?"] = "Kto widzi Władze gildii?"
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "Kto jak stoi u której frakcji? Tuż przed celem, wspólne farmienie, postęp w tym tygodniu"
T["Wer stirbt am oeftesten, woran und wo - die Todes-Rangliste der Gilde"] = "Kto ginie najczęściej, od czego i gdzie - gildyjny ranking śmierci"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "Kto zadaje, leczy i przyjmuje najwięcej?"
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "Kto dawno nie był online - posprzątaj jednym kliknięciem."
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "Kto należy do władz, ustala mistrz gildii w Korona > Gildia."
T["Werbung"] = "Rekrutacja"
T["Werkzeuge"] = "Narzędzia"
T["Werte"] = "Statystyki"
T["Werte bringen deiner Rolle nichts"] = "statystyki nic nie dają Twojej roli"
T["Werte nur zur Info"] = "statystyki tylko informacyjnie"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Statystyki, rocznik, cel dnia, rekordy i przygody Twojej postaci."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Statystyki: +leczenie, intelekt, duch, mp5;Broń: kostur lub jednoręczna + off-hand z leczeniem;Leczenie: Rejuvenation i Regrowth z wyprzedzeniem, Healing Touch na duże trafienia;Wskazówka: Innervate na manę, Rebirth dla poległych healerów"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Statystyki: +leczenie, intelekt, kryt zaklęć (Illumination zwraca manę), mp5;Broń: jednoręczna + off-hand/tarcza z leczeniem;Leczenie: Flash of Light na małe obrażenia, Holy Light (niska ranga) na duże trafienia;Wskazówka: rozdawaj blessingi, Divine Protection, gdy złapiesz aggro"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Statystyki: +leczenie, mp5, intelekt - duch daje niewiele;Broń: jednoręczna + tarcza z leczeniem;Leczenie: Chain Heal na grupy, Healing Wave (niska ranga) na tanka;Wskazówka: stawiaj Mana Spring Totem, Earth Shield na tanka"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Statystyki: +leczenie, duch (Meditation: regeneracja także podczas czarowania), intelekt, mp5;Broń: kostur lub jednoręczna + off-hand z leczeniem, różdżka;Leczenie: Renew i Power Word: Shield z wyprzedzeniem, Greater Heal (niska ranga) na tanka;Wskazówka: Prayer of Healing na grupę, Fade przy aggro"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Statystyki: pancerz (forma niedźwiedzia go mnoży), wytrzymałość, zręczność (unik + pancerz);Broń: obrażenia bez znaczenia - liczą się tylko statystyki (kostur/broń drzewcowa z wytrzymałością);Rotacja: Maul, Swipe na grupy, Demoralizing Roar;Wskazówka: siła na większy threat, Enrage na start"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Statystyki: siła (1 punkt = 2 AP), zręczność (AP + kryt), kryt, trafienie do +9 %;Broń: obrażenia bez znaczenia - liczą się tylko statystyki;Rotacja: Claw/Shred na combo pointy, potem Ferocious Bite;Wskazówka: powershift (ponowna zmiana formy) dla energii, otwieraj ze stealtha"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Statystyki: siła (1 punkt = 2 AP), kryt (wyzwala Flurry = szybsze ciosy), trafienie do +9 %;Broń: wolna dwuręczna - Windfury wyzwala się przy ciosie, więc im wolniejsza, tym więcej obrażeń;Rotacja: Windfury Weapon, Stormstrike, Earth Shock;Wskazówka: Strength of Earth Totem i Windfury Totem dla grupy"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Statystyki: siła (1 punkt = 2 AP), kryt, trafienie do +9 %;Broń: wolna dwuręczna - seale i Judgement działają od ciosu;Rotacja: Seal of Righteousness/Command, Judgement, odnów seal;Wskazówka: Consecration tylko przy zapasie many, Blessing of Might na siebie"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Statystyki: trafienie do +9 %, zręczność (1 AP, ok. 29 = 1 % kryta), AP, kryt;Broń: Combat = szybki off-hand, wolna główna ręka (Sinister Strike); sztylety do Backstab;Rotacja: buduj combo pointy, utrzymuj Slice and Dice, potem Eviscerate;Wskazówka: z dwiema broniami zwykłe ciosy częściej pudłują - trafienie jest najważniejsze"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Statystyki: trafienie do +9 %, zręczność (2 AP dystansowe, ok. 53 = 1 % kryta), AP, intelekt;Broń: wolna broń dystansowa (duże obrażenia na strzał), broń biała ze statystykami;Rotacja: Hunter's Mark, Auto Shot, między nimi Aimed Shot/Multi-Shot;Wskazówka: karm peta i dbaj o jego zadowolenie, Freezing Trap (kwadrat) do kontroli"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Statystyki: trafienie do +9 %, siła (1 punkt = 2 AP), kryt (ok. 20 zręczności = 1 %);Broń: wolna dwuręczna (Mortal Strike, Heroic Strike działają od ciosu);Rotacja: buduj rage, Mortal Strike / Bloodthirst, Whirlwind, nadmiar rage w Heroic Strike;Wskazówka: Battle Shout przed walką, Execute poniżej 20 % życia"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Statystyki: obrona (440 = odporność na kryty bossów na 60), wytrzymałość, pancerz, blok;Broń: jednoręczna + tarcza, szybka broń = więcej rage;Rotacja: Shield Slam/Revenge, Sunder Armor na cel, Heroic Strike przy dużym rage;Wskazówka: trafienie pomaga, by Taunt i umiejętności nie pudłowały"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Statystyki: obrona, wytrzymałość, pancerz, potem obrażenia zaklęć na większy threat;Broń: jednoręczna (najlepiej z obrażeniami zaklęć) + tarcza;Rotacja: włącz Righteous Fury, Consecration na grupy, utrzymuj Holy Shield;Wskazówka: many jest mało - weź Seal of Wisdom albo trochę intelektu"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Statystyki: obrażenia zaklęć, kryt zaklęć (Elemental Focus oszczędza manę), intelekt, mp5;Broń: jednoręczna + tarcza/off-hand z obrażeniami zaklęć;Rotacja: spamuj Lightning Bolt, Chain Lightning na grupy, Flame Shock;Wskazówka: trafienie zaklęć do +16 % w rajdzie, Mana Spring Totem na brak many"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Statystyki: obrażenia zaklęć, kryt zaklęć, intelekt, trafienie zaklęć do +16 % w rajdzie;Broń: kostur lub jednoręczna + off-hand z obrażeniami zaklęć;Rotacja: Moonfire + Insect Swarm, potem Wrath lub Starfire;Wskazówka: Innervate na siebie, gdy kończy się mana"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Statystyki: obrażenia zaklęć, trafienie zaklęć do +16 % (rajd), wytrzymałość, intelekt;Broń: kostur lub sztylet + off-hand z obrażeniami zaklęć, różdżka na resztki many;Rotacja: Corruption + klątwa, potem Shadow Bolt; Life Tap zamiast picia;Wskazówka: wytrzymałość opłaca się podwójnie (Life Tap, Voidwalker/Soul Link)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Statystyki: obrażenia zaklęć, trafienie zaklęć do +16 % (rajd), duch dla many;Broń: kostur lub jednoręczna + off-hand z obrażeniami zaklęć;Rotacja: Shadow Word: Pain, Mind Blast, Mind Flay;Wskazówka: stale w Shadowform, Vampiric Embrace leczy grupę"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Statystyki: obrażenia zaklęć, potem trafienie zaklęć do +16 % (bossowie rajdowi), intelekt, kryt zaklęć;Broń: kostur z obrażeniami zaklęć, do tego różdżka na resztki many;Rotacja: spamuj Frostbolt lub Fireball, Evocation przy braku many;Levelowanie: intelekt i duch = mniej przerw, w grupach owca (księżyc)"
