T["Wo ist die Gilde? Punkte auf der Weltkarte und ein Live-Radar fuer dein Gebiet"] = "Gdzie jest gildia? Punkty na mapie świata i radar na żywo dla Twojej strefy"
T["Wo ist die Gilde? Wer ist in deiner Naehe - mit Entfernung, Richtung und Punkten auf Welt- und Minimap"] = "Gdzie jest gildia? Kto jest w pobliżu - z odległością, kierunkiem i punktami na mapie świata i minimapie"
T["Wo sich die Gilde aufhaelt - aus deiner Position und allen geteilten Gilden-Positionen, jede Minute."] = "Gdzie przebywa gildia - z Twojej pozycji i wszystkich udostępnionych pozycji gildii, co minutę."
