T["WoW Classic hat keine Dungeon-Karten. Das kostenlose Addon Atlas bringt sie mit:"] = "WoW Classic nie ma map lochów. Darmowy addon Atlas je dodaje:"
T["WoW Forever Start"] = "Start"
T["WoW erlaubt das Addons nicht direkt - Enter druecken zum Verlassen."] = "WoW nie pozwala addonom zrobić tego bezpośrednio - naciśnij Enter, aby wyjść."
T["WoW erlaubt hoechstens 10 Raenge."] = "WoW pozwala na najwyżej 10 rang."
T["WoW gibt den Inhalt nur heraus, solange jemand am Gildentresor steht."] = "WoW udostępnia zawartość tylko wtedy, gdy ktoś stoi przy skarbcu gildii."
T["WoW hat die Aenderung nicht angenommen (evtl. nur in Ruhe-Zonen oder ausserhalb von Instanzen moeglich)."] = "WoW nie przyjął zmiany (być może możliwe tylko w strefach odpoczynku lub poza instancjami)."
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "W grupie WoW nie mówi addonom, kto trafił. Oasis liczy trafienie krytyczne tylko wtedy, gdy następuje bezpośrednio po Twoim ataku i po walce zgadza się z licznikiem obrażeń. W rankingu oznaczone jako szacunkowe."
T["WoW sperrt einige Funktionen fuer Addons (Kampf, Boss, Chat-Eingabe). Hier steht, welche Funktion es war und was Oasis davor gemacht hat."] = "WoW blokuje addonom niektóre funkcje (walka, boss, wpisywanie na czacie). Tu widać, która to była funkcja i co Oasis robił wcześniej."
