T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Pokazuje LEPSZE / GORSZE / NIE DO ZAŁOŻENIA z efektem (DPS, życie, pancerz) i tabelą statystyk. Porównanie Blizzarda pojawia się wtedy tylko z Shiftem. Jeśli załadowano nesUI z własnym porównaniem, Oasis nic nie pokazuje (inaczej podwójnie) - wyłącz je tam przez /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Pokazuje lepsze / gorsze / nie do założenia z efektem (DPS, życie, pancerz) i tabelą statystyk. Porównanie Blizzarda pojawia się wtedy tylko z Shiftem. Jeśli załadowano nesUI z własnym porównaniem, Oasis nic nie pokazuje (inaczej podwójnie) - wyłącz je tam przez /nes vergleich."
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "Pokazuje łup z lochów z Twojego zakresu poziomów, lepszy od założonego przedmiotu."
T["Zeigt Oasis-Nachrichten im Chat"] = "Pokazuje wiadomości Oasis na czacie"
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "Od rangi Oasis 30 pokazuje klejnot, a od rangi 70 mieniące się imię na czacie gildii Oasis"
T["Zeigt ab und zu typische Brachland-Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "Co jakiś czas pokazuje klasyczne teksty z czatu Barrens na kanale General - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane."
T["Zeigt ab und zu typische Brachland-Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet. Klick: umschalten"] = "Co jakiś czas pokazuje klasyczne teksty z czatu Barrens na kanale General - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane. Kliknij: przełącz"
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "Pokazuje, jakie materiały mogą wypaść z disenchantu zielonych, niebieskich i epickich przedmiotów"
T["Zeigt die Levelspanne der Gebiete"] = "Pokazuje zakres poziomów każdej strefy"
T["Zeigt dir die Krone und die Gildenleitung wie einem Gildenmeister - nur auf deinem PC. Die Gilde sieht davon nichts."] = "Pokazuje Ci koronę i Władze gildii jak mistrzowi gildii - tylko na Twoim PC. Gildia nic z tego nie widzi."
T["Zeigt einen Hinweis, sobald jemand aus der Gilde einen neuen Termin anlegt"] = "Pokazuje powiadomienie, gdy ktoś z gildii utworzy nowe wydarzenie"
T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "W Barrens co jakiś czas pokazuje typowe teksty na czacie ogólnym - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane."
T["Zeigt im Item-Tooltip, wer das Item fuer einen anstehenden Termin reserviert hat"] = "Pokazuje w tooltipie przedmiotu, kto zarezerwował go na nadchodzące wydarzenie"
T["Zeigt im Tooltip, wer in der Gilde das Item herstellen kann"] = "Pokazuje w tooltipie, kto w gildii może wytworzyć przedmiot"
T["Zeigt im Tooltip, wie viele davon in der Gildenbank liegen"] = "Pokazuje w tooltipie, ile sztuk leży w banku gildii"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "Pokazuje na liście, że rozmawiacie głosowo (Discord itp.). Dołączaniem nadal zarządza Blizzard / lider grupy."
T["Zeigt nur Mains. Twinks sind Charaktere, die einem anderen Main zugeordnet sind."] = "Pokazuje tylko mainy. Alty to postacie przypisane do innego maina."
T["Zeigt nur die Kopfzeile mit der Anzahl der Builds."] = "Pokazuje tylko nagłówek z liczbą buildów."
T["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "Od razu pokazuje, kto z gildii ma te same zadania i jest teraz online - jedno kliknięcie go zaprasza."
T["Zeigt unerforschte Gebiete abgedunkelt an (Standard aus)"] = "Pokazuje nieodkryte obszary przyciemnione (domyślnie wył.)"
T["Zeigt z.B. neue Nachrichten oder Auftraege als Zahl neben dem Namen"] = "Pokazuje np. nowe wiadomości lub zamówienia jako liczbę obok nazwy"
T["Zeigt, fuer wen in der Gilde ein Teil ein Upgrade ist"] = "Pokazuje, dla kogo w gildii przedmiot jest ulepszeniem"
T["Zeigt, wer aus der Gilde das Item fuer eine Quest braucht"] = "Pokazuje, kto z gildii potrzebuje przedmiotu do zadania"
T["Zeile 'Upgrade fuer' im Item-Tooltip"] = "Linia 'Ulepszenie dla' w tooltipie przedmiotu"
T["Zeile im Item-Tooltip: Gebraucht von"] = "Linia w tooltipie przedmiotu: potrzebne dla"
